1	/* Shared, side-effect-free helpers for report generation across all three
2	   verticals (retail, property, trades). Everything here is pure so it can be
3	   unit-tested without a DOM or a PDF engine — the IO (PDF share, CSV download)
4	   lives in report-pdf/savePdf.ts.
5	
6	   Money is handled in integer cents everywhere. Retail transactions store
7	   `price` as a decimal-dollar string, so cross that boundary with
8	   dollarsToCents() at the edge and stay in cents thereafter. GST math is NZ
9	   15% and is always computed on a total (never summed per-line) so it can
10	   never drift a cent from what an accountant would compute. Dates are
11	   formatted and bucketed in Pacific/Auckland — a payment at 11pm NZ on the
12	   last of the month must land in that month's GST period, not the next. */
13	
14	export const NZ_TZ = "Pacific/Auckland";
15	export const GST_RATE = 0.15;
16	
17	/* ── Money ──────────────────────────────────────────────────────────── */
18	
19	/** Parse a decimal-dollar string/number (retail `price`) into integer cents. */
20	export function dollarsToCents(v: string | number | null | undefined): number {
21	  if (v == null || v === "") return 0;
22	  const n = typeof v === "number" ? v : parseFloat(v);
23	  if (!isFinite(n)) return 0;
24	  return Math.round(n * 100);
25	}
26	
27	/** "$1,234.56" — pass withCode for the "$1,234.56 NZD" report-header form. */
28	export function fmtNZD(cents: number, withCode = false): string {
29	  const neg = cents < 0;
30	  const dollars = Math.abs(cents) / 100;
31	  const body = dollars.toLocaleString("en-NZ", {
32	    minimumFractionDigits: 2,
33	    maximumFractionDigits: 2,
34	  });
35	  return `${neg ? "-" : ""}$${body}${withCode ? " NZD" : ""}`;
36	}
37	
38	/* ── GST (NZ 15%) ───────────────────────────────────────────────────── */
39	
40	export interface GstBreakdown {
41	  excl: number; // cents excluding GST
42	  gst: number; // cents of GST
43	  incl: number; // cents including GST
44	}
45	
46	/** GST-inclusive total → its excl/gst/incl split, in whole cents. */
47	export function calcGST(centsInclGst: number): GstBreakdown {
48	  const excl = Math.round(centsInclGst / (1 + GST_RATE));
49	  return { excl, gst: centsInclGst - excl, incl: centsInclGst };
50	}
51	
52	/** GST-exclusive (net) amount → its split, in whole cents. */
53	export function calcGSTExclusive(centsExclGst: number): GstBreakdown {
54	  const gst = Math.round(centsExclGst * GST_RATE);
55	  return { excl: centsExclGst, gst, incl: centsExclGst + gst };
56	}
57	
58	/** Interpret `cents` per the merchant's trade GST mode ("inclusive" default). */
59	export function calcGSTByMode(cents: number, mode?: string | null): GstBreakdown {
60	  return mode === "exclusive" ? calcGSTExclusive(cents) : calcGST(cents);
61	}
62	
63	/* ── Dates (all formatting/bucketing in NZ time) ────────────────────── */
64	
65	const nzParts = (d: Date) => {
66	  const p = new Intl.DateTimeFormat("en-NZ", {
67	    timeZone: NZ_TZ,
68	    year: "numeric",
69	    month: "2-digit",
70	    day: "2-digit",
71	  }).formatToParts(d);
72	  const get = (t: string) => p.find((x) => x.type === t)?.value ?? "";
73	  return { day: get("day"), month: get("month"), year: get("year") };
74	};
75	
76	const MONTHS_SHORT = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];
77	
78	export function toDate(v: Date | string | number | null | undefined): Date | null {
79	  if (v == null) return null;
80	  const d = v instanceof Date ? v : new Date(v);
81	  return isNaN(d.getTime()) ? null : d;
82	}
83	
84	/** dd/mm/yyyy in NZ time. Returns "" for null/invalid so tables don't print "Invalid Date". */
85	export function fmtDate(v: Date | string | number | null | undefined): string {
86	  const d = toDate(v);
87	  if (!d) return "";
88	  const { day, month, year } = nzParts(d);
89	  return `${day}/${month}/${year}`;
90	}
91	
92	/** "5 Jun 2026, 2:04 PM" NZ time — for transaction ledgers. */
93	export function fmtDateTime(v: Date | string | number | null | undefined): string {
94	  const d = toDate(v);
95	  if (!d) return "";
96	  return new Intl.DateTimeFormat("en-NZ", {
97	    timeZone: NZ_TZ,
98	    day: "numeric",
99	    month: "short",
100	    year: "numeric",
101	    hour: "numeric",
102	    minute: "2-digit",
103	    hour12: true,
104	  }).format(d);
105	}
