107	/** "1 Jun – 30 Jun 2026" (collapses the year when the range shares one). */
108	export function dateRangeLabel(start: Date, end: Date): string {
109	  const s = nzParts(start);
110	  const e = nzParts(end);
111	  const sMon = MONTHS_SHORT[parseInt(s.month, 10) - 1];
112	  const eMon = MONTHS_SHORT[parseInt(e.month, 10) - 1];
113	  const left = s.year === e.year ? `${parseInt(s.day, 10)} ${sMon}` : `${parseInt(s.day, 10)} ${sMon} ${s.year}`;
114	  const right = `${parseInt(e.day, 10)} ${eMon} ${e.year}`;
115	  return `${left} – ${right}`;
116	}
117	
118	/** Whole days a due date is overdue as of `asOf` (0 if not yet due). */
119	export function daysOverdue(dueAt: Date | string | number | null | undefined, asOf: Date = new Date()): number {
120	  const due = toDate(dueAt);
121	  if (!due) return 0;
122	  const ms = asOf.getTime() - due.getTime();
123	  if (ms <= 0) return 0;
124	  return Math.floor(ms / 86_400_000);
125	}
126	
127	/* ── Timeframe → date window (NZ-aligned) ───────────────────────────── */
128	
129	export type Timeframe = "day" | "week" | "month" | "year";
130	
131	/** [start, end) window for a preset timeframe, ending at `now`.
132	   Week is Monday-start to match the dashboards' periodWindow(). */
133	export function timeframeWindow(tf: Timeframe, now: Date = new Date()): { start: Date; end: Date } {
134	  const end = now;
135	  const start = new Date(now);
136	  switch (tf) {
137	    case "day":
138	      start.setHours(0, 0, 0, 0);
139	      break;
140	    case "week": {
141	      const dow = (start.getDay() + 6) % 7; // 0 = Monday
142	      start.setDate(start.getDate() - dow);
143	      start.setHours(0, 0, 0, 0);
144	      break;
145	    }
146	    case "month":
147	      start.setDate(1);
148	      start.setHours(0, 0, 0, 0);
149	      break;
150	    case "year":
151	      start.setMonth(0, 1);
152	      start.setHours(0, 0, 0, 0);
153	      break;
154	  }
155	  return { start, end };
156	}
157	
158	/** True when `when` falls within [start, end]. Null dates are excluded. */
159	export function inRange(when: Date | string | number | null | undefined, start: Date, end: Date): boolean {
160	  const d = toDate(when);
161	  if (!d) return false;
162	  const t = d.getTime();
163	  return t >= start.getTime() && t <= end.getTime();
164	}
165	
166	/* ── Aged buckets (shared by Property Arrears + Trades Receivables) ──── */
167	
168	export const AGE_BUCKETS = [
169	  { key: "1-7", label: "1–7 days", min: 1, max: 7 },
170	  { key: "8-30", label: "8–30 days", min: 8, max: 30 },
171	  { key: "31-60", label: "31–60 days", min: 31, max: 60 },
172	  { key: "60+", label: "60+ days", min: 61, max: Infinity },
173	] as const;
174	
175	export interface AgedBucket<T> {
176	  key: string;
177	  label: string;
178	  rows: T[];
179	  totalCents: number;
180	}
181	
182	/** Group overdue items into age buckets. `getDue` reads the due date, `getCents`
183	   the amount owed. Items not yet overdue (daysOverdue === 0) are dropped. */
184	export function agedBuckets<T>(
185	  items: T[],
186	  getDue: (t: T) => Date | string | number | null | undefined,
187	  getCents: (t: T) => number,
188	  asOf: Date = new Date(),
189	): { buckets: AgedBucket<T>[]; grandTotalCents: number } {
190	  const buckets: AgedBucket<T>[] = AGE_BUCKETS.map((b) => ({ key: b.key, label: b.label, rows: [], totalCents: 0 }));
191	  let grand = 0;
192	  for (const item of items) {
193	    const days = daysOverdue(getDue(item), asOf);
194	    if (days < 1) continue;
195	    const idx = AGE_BUCKETS.findIndex((b) => days >= b.min && days <= b.max);
196	    if (idx < 0) continue;
197	    const cents = getCents(item);
198	    buckets[idx].rows.push(item);
199	    buckets[idx].totalCents += cents;
200	    grand += cents;
201	  }
202	  return { buckets, grandTotalCents: grand };
203	}
204	
205	/* ── CSV ────────────────────────────────────────────────────────────── */
206	
207	/** Escape one CSV field: quote-wrap when needed, and neutralise formula
208	   injection (a leading = + - @ makes Excel/Sheets execute the cell). */
209	export function csvCell(value: unknown): string {
210	  let s = value == null ? "" : String(value);
211	  if (/^[=+\-@\t\r]/.test(s)) s = "'" + s; // formula-injection guard
212	  if (/[",\n\r]/.test(s)) s = '"' + s.replace(/"/g, '""') + '"';
213	  return s;
214	}
215	
216	/** Build a CSV string from a header row and body rows. */
217	export function buildCSV(headers: string[], rows: (unknown[])[]): string {
218	  const lines = [headers.map(csvCell).join(",")];
219	  for (const row of rows) lines.push(row.map(csvCell).join(","));
220	  return lines.join("\r\n");
221	}
222	
223	/* ── Small numeric helpers ──────────────────────────────────────────── */
224	
225	/** Percentage 0–100, rounded to `dp`; null when the denominator is 0 so
226	   callers render "—" instead of NaN%. */
227	export function ratePct(numerator: number, denominator: number, dp = 0): number | null {
228	  if (!denominator) return null;
229	  const f = Math.pow(10, dp);
230	  return Math.round((numerator / denominator) * 100 * f) / f;
231	}
232	
233	/** "72%" or "—" for a rate produced by ratePct(). */
234	export function fmtPct(v: number | null): string {
235	  return v == null ? "—" : `${v}%`;
236	}
237	
238	export function sumCents<T>(items: T[], getCents: (t: T) => number): number {
239	  let total = 0;
240	  for (const i of items) total += getCents(i) || 0;
241	  return total;
242	}
