1	/* Reusable @react-pdf building blocks shared by all eleven reports. Report
2	   files never touch raw @react-pdf styling — they compose <ReportPage>,
3	   <KpiRow>, <DataTable>, <ReportBarChart>, etc. */
4	import React from "react";
5	import { Document, Page, View, Text, Svg, Rect, Path, Circle, G } from "@react-pdf/renderer";
6	
7	import { COLORS, PAGE, styles, ensureFonts } from "./theme";
8	import { fmtNZD } from "../report-utils";
9	
10	/* Content width of an A4 page inside the horizontal padding, in points.
11	   595.28pt (A4 width) − 2×40pt padding ≈ 515pt. Charts and equal-flex label
12	   rows both assume this width so bars and their labels line up. */
13	export const CONTENT_W = 515;
14	
15	export interface MerchantHeader {
16	  businessName?: string | null;
17	  gstNumber?: string | null;
18	  nzbn?: string | null;
19	  gstRegistered?: boolean | null;
20	}
21	
22	/* ── Page shell: cover band on p1, running header p2+, footer everywhere ── */
23	export function ReportPage({
24	  merchant,
25	  title,
26	  period,
27	  children,
28	}: {
29	  merchant: MerchantHeader;
30	  title: string;
31	  period?: string;
32	  children: React.ReactNode;
33	}) {
34	  ensureFonts();
35	  const meta = [
36	    merchant.gstNumber ? `GST ${merchant.gstNumber}` : null,
37	    merchant.nzbn ? `NZBN ${merchant.nzbn}` : null,
38	  ]
39	    .filter(Boolean)
40	    .join("   ·   ");
41	
42	  return (
43	    <Page size={PAGE.size} style={styles.page} wrap>
44	      {/* Running header — only pages 2+ (cover carries the branding on p1) */}
45	      <View
46	        style={styles.runHeader}
47	        fixed
48	        render={({ pageNumber }) =>
49	          pageNumber > 1 ? (
50	            <>
51	              <Text>{merchant.businessName || "TaptPay"}</Text>
52	              <Text>{title}</Text>
