/* IO edge for report generation: turn a composed @react-pdf <Document> into a
   file the merchant actually receives. Everything upstream — report-utils and
   the per-vertical report files — is pure and unit-testable; all the
   browser-only surface (Blob URLs, the Web Share sheet, anchor downloads) is
   quarantined here so nothing else has to stub `navigator` or the DOM.

   Mobile-first, matching how the app is used in a webview on a phone: when the
   OS can share a file we hand the PDF straight to the native share sheet
   (Mail, Messages, "Save to Files", AirDrop); everywhere else we fall back to a
   plain download. CSV is always a direct download. */
import { pdf } from "@react-pdf/renderer";

/* The element type `pdf()` accepts (a <Document> at the root). Derived from the
   function itself because @react-pdf doesn't export DocumentProps by name. */
export type ReportDoc = NonNullable<Parameters<typeof pdf>[0]>;

/** Strip anything a filename or Content-Disposition header would choke on and
   guarantee the extension. "Rent Roll – June 2026" → "rent-roll-june-2026.pdf". */
export function reportFilename(base: string, ext: "pdf" | "csv"): string {
  const stem = base
    .normalize("NFKD")
    .replace(/[^\w\s.-]/g, "") // drop punctuation, em dashes, emoji, macrons decomposed above
    .trim()
    .replace(/\s+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^[-.]+|[-.]+$/g, "")
    .toLowerCase();
  const name = stem || "taptpay-report";
  return name.endsWith(`.${ext}`) ? name : `${name}.${ext}`;
}

/** Render a composed report Document to a PDF Blob. Resolves once @react-pdf
   has laid out every page and embedded the fonts. */
export function renderPdfBlob(doc: ReportDoc): Promise<Blob> {
  return pdf(doc).toBlob();
}

/** Push any Blob to the user as a download via a short-lived object URL. */
function triggerDownload(blob: Blob, filename: string) {
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.rel = "noopener";
  document.body.appendChild(a);
  a.click();
  a.remove();
  // Revoke on the next tick so the click has committed before the URL dies.
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

/** Whether this device can share an actual File through the OS share sheet
   (true on most phones, false on desktop browsers). Guarded because
   `canShare` throws on some engines when handed a files payload. */
function canShareFile(file: File): boolean {
  try {
    return typeof navigator !== "undefined" && typeof navigator.canShare === "function" && navigator.canShare({ files: [file] });
  } catch {
    return false;
  }
}

export type SaveMethod = "share" | "download";

/** Render `doc` and deliver it to the merchant. On a share-capable phone this
   opens the native share sheet; otherwise it downloads directly. Dismissing the
   share sheet is a deliberate no-op — it resolves as "share", never rejects, so
   callers don't surface a scary error toast for a cancel. `title` seeds the
   share sheet's subject line. */
export async function savePdf(doc: ReportDoc, filename: string, title?: string): Promise<SaveMethod> {
  const name = reportFilename(filename, "pdf");
  const blob = await renderPdfBlob(doc);
  const file = new File([blob], name, { type: "application/pdf" });

  if (canShareFile(file)) {
    try {
      await navigator.share({ files: [file], title: title ?? name });
      return "share";
    } catch (err) {
      // AbortError = the user closed the sheet on purpose; respect it and stop.
      // Anything else (share unsupported for this payload, transient failure)
      // falls through to a download so they still get their report.
      if (err instanceof DOMException && err.name === "AbortError") return "share";
    }
  }

  triggerDownload(blob, name);
  return "download";
}

/** Download a CSV string (produced by report-utils buildCSV). Prepends a UTF-8
   BOM so Excel on Windows reads NZ characters as UTF-8 rather than Latin-1. */
export function downloadCsv(csv: string, filename: string) {
  const blob = new Blob(["﻿" + csv], { type: "text/csv;charset=utf-8" });
  triggerDownload(blob, reportFilename(filename, "csv"));
}

