1	/* Pure data helpers for the property dashboard — bucketing, growth, collection
2	   rate, and the per-property filter. All figures exclude voided invoices. */
3	
4	export type Timeframe = 'day' | 'week' | 'month' | 'year';
5	export interface Bucket { label: string; valueCents: number }
6	
7	const isPaid = (i: any) => i.status === 'paid' || i.status === 'paid_external';
8	const notVoided = (invs: any[]) => invs.filter((i: any) => i.status !== 'voided');
9	const paidAt = (i: any) => new Date(i.paidAt ?? i.createdAt);
10	const sumCents = (invs: any[]) => invs.reduce((s: number, i: any) => s + (i.amountCents ?? 0), 0);
11	const inWin = (d: Date, s: Date, e: Date) => d >= s && d < e;
12	
13	/* Current + previous window for a timeframe. Week is Monday-start; month/year
14	   are calendar periods; day is a rolling 24h. */
15	export function periodWindow(tf: Timeframe, now = new Date()) {
16	  if (tf === 'day') {
17	    const start = new Date(now.getTime() - 24 * 3600000);
18	    return { start, end: now, prevStart: new Date(now.getTime() - 48 * 3600000), prevEnd: start };
19	  }
20	  if (tf === 'week') {
21	    const d = new Date(now); d.setHours(0, 0, 0, 0);
22	    const start = new Date(d); start.setDate(d.getDate() - ((d.getDay() + 6) % 7)); // Monday
23	    const prevStart = new Date(start); prevStart.setDate(start.getDate() - 7);
24	    return { start, end: now, prevStart, prevEnd: start };
25	  }
26	  if (tf === 'month') {
27	    const start = new Date(now.getFullYear(), now.getMonth(), 1);
28	    return { start, end: now, prevStart: new Date(now.getFullYear(), now.getMonth() - 1, 1), prevEnd: start };
29	  }
30	  const start = new Date(now.getFullYear(), 0, 1);
31	  return { start, end: now, prevStart: new Date(now.getFullYear() - 1, 0, 1), prevEnd: start };
32	}
33	
34	/* Rent collected (paid invoices, by paid date) inside [start, end). */
35	export function collectedCents(invoices: any[], start: Date, end: Date): number {
36	  return sumCents(notVoided(invoices).filter(isPaid).filter((i: any) => inWin(paidAt(i), start, end)));
37	}
38	
39	/* % change vs previous period; null when there's no previous baseline. */
40	export function growthPct(current: number, previous: number): number | null {
41	  if (previous <= 0) return null;
42	  return Math.round(((current - previous) / previous) * 100);
43	}
