51	/* ── Add Tenant Sheet ── */
52	function AddTenantSheet({ onClose, onSave, saving, saveError }: {
53	  onClose: () => void;
54	  onSave: (data: any) => void;
55	  saving: boolean;
56	  saveError: string | null;
57	}) {
58	  const [form, setForm] = useState({
59	    firstName: '', lastName: '', email: '', phone: '',
60	    propertyAddress: '', preferredChannel: 'email' as 'email' | 'whatsapp' | 'sms',
61	  });
62	  const [subtenants, setSubtenants] = useState<{ name: string; email: string; phone: string }[]>([]);
63	  const [subForm, setSubForm]       = useState({ name: '', email: '', phone: '' });
64	  const [subOpen, setSubOpen]       = useState(false);
65	  const [closing, setClosing]       = useState(false);
66	
67	  const set    = (k: string) => (v: string) => setForm(f => ({ ...f, [k]: v }));
68	  const setSub = (k: string) => (v: string) => setSubForm(f => ({ ...f, [k]: v }));
69	
70	  // The chosen delivery channel must have a matching contact, or the rent link
71	  // can't be delivered: email → email address; whatsapp/sms → phone number.
72	  const channelContactOk = form.preferredChannel === 'email' ? !!form.email.trim() : !!form.phone.trim();
73	  const valid = form.firstName.trim() && form.lastName.trim() && form.propertyAddress.trim() && channelContactOk;
74	
75	  const handleClose = () => {
76	    setClosing(true);
77	    setTimeout(onClose, 320);
