content.content:
1	/* IO edge for report generation: turn a composed @react-pdf <Document> into a
2	   file the merchant actually receives. Everything upstream — report-utils and
3	   the per-vertical report files — is pure and unit-testable; all the
4	   browser-only surface (Blob URLs, the Web Share sheet, anchor downloads) is
5	   quarantined here so nothing else has to stub `navigator` or the DOM.
6	
7	   Mobile-first, matching how the app is used in a webview on a phone: when the
8	   OS can share a file we hand the PDF straight to the native share sheet
9	   (Mail, Messages, "Save to Files", AirDrop); everywhere else we fall back to a
10	   plain download. CSV is always a direct download. */
11	import { pdf } from "@react-pdf/renderer";
12	
13	/* The element type `pdf()` accepts (a <Document> at the root). Derived from the
14	   function itself because @react-pdf doesn't export DocumentProps by name. */
15	export type ReportDoc = NonNullable<Parameters<typeof pdf>[0]>;
16	
17	/** Strip anything a filename or Content-Disposition header would choke on and
18	   guarantee the extension. "Rent Roll – June 2026" → "rent-roll-june-2026.pdf". */
19	export function reportFilename(base: string, ext: "pdf" | "csv"): string {
20	  const stem = base
21	    .normalize("NFKD")
22	    .replace(/[^\w\s.-]/g, "") // drop punctuation, em dashes, emoji, macrons decomposed above
23	    .trim()
24	    .replace(/\s+/g, "-")
25	    .replace(/-+/g, "-")
26	    .replace(/^[-.]+|[-.]+$/g, "")
27	    .toLowerCase();
28	  const name = stem || "taptpay-report";
29	  return name.endsWith(`.${ext}`) ? name : `${name}.${ext}`;
30	}
31	
32	/** Render a composed report Document to a PDF Blob. Resolves once @react-pdf
33	   has laid out every page and embedded the fonts. */
34	export function renderPdfBlob(doc: ReportDoc): Promise<Blob> {
35	  return pdf(doc).toBlob();
36	}
37	
38	/** Push any Blob to the user as a download via a short-lived object URL. */
39	function triggerDownload(blob: Blob, filename: string) {
40	  const url = URL.createObjectURL(blob);
41	  const a = document.createElement("a");
42	  a.href = url;
43	  a.download = filename;
44	  a.rel = "noopener";
45	  document.body.appendChild(a);
46	  a.click();
47	  a.remove();
48	  // Revoke on the next tick so the click has committed before the URL dies.
49	  setTimeout(() => URL.revokeObjectURL(url), 0);
50	}
51	
52	/** Whether this device can share an actual File through the OS share sheet
53	   (true on most phones, false on desktop browsers). Guarded because
54	   `canShare` throws on some engines when handed a files payload. */
55	function canShareFile(file: File): boolean {
56	  try {
57	    return typeof navigator !== "undefined" && typeof navigator.canShare === "function" && navigator.canShare({ files: [file] });
58	  } catch {
59	    return false;
60	  }
61	}
62	
63	export type SaveMethod = "share" | "download";
64	
65	/** Render `doc` and deliver it to the merchant. On a share-capable phone this
66	   opens the native share sheet; otherwise it downloads directly. Dismissing the
67	   share sheet is a deliberate no-op — it resolves as "share", never rejects, so
68	   callers don't surface a scary error toast for a cancel. `title` seeds the
69	   share sheet's subject line. */
70	export async function savePdf(doc: ReportDoc, filename: string, title?: string): Promise<SaveMethod> {
71	  const name = reportFilename(filename, "pdf");
72	  const blob = await renderPdfBlob(doc);
73	  const file = new File([blob], name, { type: "application/pdf" });
74	
75	  if (canShareFile(file)) {
76	    try {
77	      await navigator.share({ files: [file], title: title ?? name });
78	      return "share";
79	    } catch (err) {
80	      // AbortError = the user closed the sheet on purpose; respect it and stop.
81	      // Anything else (share unsupported for this payload, transient failure)
82	      // falls through to a download so they still get their report.
83	      if (err instanceof DOMException && err.name === "AbortError") return "share";
84	    }
85	  }
86	
87	  triggerDownload(blob, name);
88	  return "download";
89	}
90	
91	/** Download a CSV string (produced by report-utils buildCSV). Prepends a UTF-8
92	   BOM so Excel on Windows reads NZ characters as UTF-8 rather than Latin-1. */
93	export function downloadCsv(csv: string, filename: string) {
94	  const BOM = String.fromCharCode(0xfeff); // UTF-8 BOM for Excel/Windows
95	  const blob = new Blob([BOM + csv], { type: "text/csv;charset=utf-8" });
96	  triggerDownload(blob, reportFilename(filename, "csv"));
97	}
98

